function getRig(root){const rig={body:root.getObjectByName('body'),arms:[],legs:[]};root.traverse(o=>{if(o.name.startsWith('leg'))rig.legs.push(o);if(o.name.startsWith('arm'))rig.arms.push(o);});return rig;}
