const joystick=$('joystick');joystick.addEventListener('pointerdown',event=>{if(paused||backgrounded||!ready||joystickPointer!==null)return;event.preventDefault();joystickPointer=event.pointerId;joystick.setPointerCapture(event.pointerId);awaken();updateJoystick(event);});joystick.addEventListener('pointermove',event=>{if(event.pointerId===joystickPointer)updateJoystick(event);});function releaseJoystick(){const pointerId=joystickPointer;joystickPointer=null;joystickValue={x:0,y:0};$('joystick-thumb').style.transform='';const stick=$('joystick');if(pointerId!==null&&stick.hasPointerCapture(pointerId))stick.releasePointerCapture(pointerId);}for(const type of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(type,event=>{if(event.pointerId===joystickPointer)releaseJoystick();});function updateJoystick(event){const r=joystick.getBoundingClientRect(),x=event.clientX-r.left-r.width/2,y=event.clientY-r.top-r.height/2,length=Math.hypot(x,y),scale=Math.min(34,length)/Math.max(1,length);joystickValue={x:x*scale/34,y:y*scale/34};$('joystick-thumb').style.transform=`translate(${x*scale}px,${y*scale}px)`;}
