function damageEnemy(e,amount,magic=false){if(e.dead)return;amount=Math.round(amount);const dealt=Math.min(e.hp,amount);e.hp-=amount;e.flash=.09;e.recoil=.22;floatText(String(dealt),e.model.position,magic?'magic':'');if(magic)particles(e.model.position.clone().add(new T.Vector3(0,.9,0)),0xffb565,20,2);else steelImpact(e.model.position.clone().add(new T.Vector3(0,e.type==='hound'?.6:1.1,0)));if(!magic)audioAt('impact',e.model.position,.64);shake=Math.max(shake,reducedMotion?0:.045);updateEnemyBar(e);if(e.hp<=0){e.dead=true;e.phase='dead';e.timer=1;cancelAttack(e);e.bar.visible=false;const oldLevel=state.level;const reward=awardKill(state,e.type);audioAt(e.type==='boss'?'death-boss':e.type==='hound'?'death-hound':e.type==='revenant'?'death-revenant':'death',e.model.position,e.type==='boss'?.82:.52);floatText(`+${reward} souls`,e.model.position,'small');life.addLoot(rollLoot(state,e.type,e.zone),e.model.position);if(lockedEnemy===e){lockedEnemy=null;attackHeld=false;}if(state.level>oldLevel){toast(`Oath strengthened · Level ${state.level}`);audio.play('levelup',.65);ringEffect(player.position,0xd6c490,.2,2.7,1);}if(e.type==='boss'){ringEffect(e.model.position,0xbacdad,.5,12,2);audioAt('bell',e.model.position,.46,.88);$('boss-bar').hidden=true;toast('The Bellkeeper falls · Claim his golden relic with F');}else{if(e.zone==='hallowmere')state.villageKills++;else state.roadKills++;if(state.villageKills===SPAWNS.length)spawnBoss();}}}
