function spawnBoss(){if(state.bossSpawned)return;state.bossSpawned=true;const boss=spawnEnemy('boss',0,-8.8);boss.cooldown=2.6;particles(boss.model.position,0xbc8660,70,4);ringEffect(boss.model.position,0xe29f6e,.2,3,1.4);audioAt('roar',boss.model.position,.82);audioAt('bell',boss.model.position,.55);toast('The Bellkeeper has answered.');$('boss-bar').hidden=false;$('enemy-target').hidden=true;}
