function particles(pos,color,count,speed){const values=new Float32Array(count*3),velocity=new Float32Array(count*3);for(let i=0;i<count;i++){velocity[i*3]=(Math.random()-.5)*speed*2;velocity[i*3+1]=Math.random()*speed+1;velocity[i*3+2]=(Math.random()-.5)*speed*2;}const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(values,3));const mesh=new T.Points(g,new T.PointsMaterial({color,size:.065,transparent:true,opacity:.9,depthWrite:false,blending:T.AdditiveBlending}));mesh.position.copy(pos);scene.add(mesh);effects.push({type:'particles',mesh,velocity,time:0,life:.75});}
