// Sound locations use the player's ears and the isometric camera's horizontal axis.
function audioAt(cue,position,volume=1,rate=1){audio.listener={x:player.position.x,z:player.position.z};return audio.play(cue,volume,rate,{position,occluded:!hasLineOfSight(player.position,position,environment.obstacles,.1)});}
function footstepCue(){const room=environment.currentBuilding(player.position);if(room)return room.chapel?'step':'step-wood';return zoneAt(player.position)==='road'&&Math.abs(player.position.z-5)>1.8?'step-dirt':'step';}
function updateAudioWorld(dt){const room=environment.currentBuilding(player.position),interior=room?.id??null;if(interior!==audioInterior){if(started)audio.play('door',.44);audioInterior=interior;}let threat=0;if(!state.ended&&!isSanctuary(player.position))for(const e of enemies)if(!e.dead){const proximity=Math.max(0,1-distance(player.position,e.model.position)/13);threat+=proximity*(e.type==='boss'?1:.42);}audio.update(dt,{zone:state.zone,position:player.position,interior:!!room,threat:Math.min(1,threat),health:state.hp/state.maxHp,ended:state.ended,victory:state.victory});}
