function talkTo(id){awaken();const npc=life.npcs.find(n=>n.id===id);if(!npc||distance(player.position,npc.model.position)>2.8)return false;if(!state.talkedTo.includes(id))state.talkedTo.push(id);currentNpc=id;showModal('npc');return true;}
function lootCollected(drop,result){audio.play(drop.template==='bellkeeper-edge'?'relic':drop.kind==='item'?'equip':'pickup',.65);toast(drop.kind==='gold'?`+${drop.amount} crowns`:drop.kind==='item'?`${drop.name} recovered · Open inventory with I`:`${drop.amount} healing draught${drop.amount>1?'s':''} recovered`);if(drop.template==='bellkeeper-edge'&&!victoryShown){victoryShown=true;setTimeout(()=>{if(!state.ended)showModal('victory');},900);}updateUI();}
